'use strict';
// Invoice and shared commercial header are maintained on the parent schedule.
LoadingPlans.headerLabels={invoice_no:'发票号（Invoice No.）',packing_list_no:'装箱单号（Packing List No.）',export_license_no:'出口许可证号（Export License No.）',transporter:'运输商（Transporter）',destination:'目的地（Destination）'};
LoadingPlans.labels={invoice_no:'发票号（Invoice No.）',...LoadingPlans.labels};
LoadingPlans.headerFields=function(g={},locked=false){return `<h3>公共运输资料</h3><div class="form-grid">${Object.entries(this.headerLabels).map(([key,label])=>`<label>${label}${key==='destination'?`<textarea name="${key}" maxlength="1000" ${locked?'readonly':''}>${esc(g[key]||'')}</textarea>`:`<input name="${key}" value="${esc(g[key]||'')}" maxlength="${key==='invoice_no'?78:key==='packing_list_no'?80:160}" ${key==='packing_list_no'||locked?'readonly':''} ${key==='invoice_no'&&(!g.id||g.invoice_no)?'required':''}>`}</label>`).join('')}</div><p class="lp-auto-number-note">装箱单号由发票号加PL自动生成，不可手工填写。</p>`;};
LoadingPlans.groupForm=async function(id){const data=id?await API.request('/loading-plans/'+id):null,g=data?.group,locked=data?.documents.some(d=>d.status==='OUTBOUND'),plans=g?[]:(await API.request('/plans')).items.filter(p=>p.status==='OPEN'&&p.contract_id);if(g?.cancelled_at)throw Error('装车计划已取消');Router.page(g?'编辑装车计划':'新建装车计划',`<form id="lp-form" class="user-form">${g?this.context(g):`<label>关联销售计划<select name="sales_plan_id" required><option value="">请选择销售计划</option>${plans.map(p=>`<option value="${p.id}">${esc(p.code+' · '+p.customer_name+' · '+p.contract_no)}</option>`).join('')}</select></label><div id="lp-plan-context"></div>`}<label>装车计划名称<input name="name" required maxlength="160" value="${esc(g?.name||'')}"></label>${this.headerFields(g,locked)}${locked?'<p class="dialog-notice">已有车辆正式出库，发票及公共运输资料已锁定。</p>':''}<label>说明<textarea name="note" maxlength="1000">${esc(g?.note||'')}</textarea></label><button class="button primary">保存装车计划</button><p class="error" id="lp-error" role="alert"></p></form>`);const form=$('lp-form');if(!g)form.elements.sales_plan_id.onchange=()=>{const p=plans.find(p=>p.id===form.elements.sales_plan_id.value);$('lp-plan-context').innerHTML=p?this.context({...p,sales_plan_code:p.code}):'';};form.elements.invoice_no.addEventListener('input',()=>{form.elements.packing_list_no.value=form.elements.invoice_no.value.trim()?form.elements.invoice_no.value.trim()+'PL':'';});form.onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const body=Object.fromEntries(new FormData(form));if(g)body.version=g.version;if(g&&!g.invoice_no&&!body.invoice_no.trim()){delete body.invoice_no;delete body.packing_list_no;}if(locked)for(const key of Object.keys(this.headerLabels))delete body[key];const r=await API.request('/loading-plans'+(g?'/'+id:''),{method:g?'PATCH':'POST',body});await Router.go('/loading-plans/'+r.id);}catch(err){$('lp-error').textContent=err.message;e.submitter.disabled=false;}};};
LoadingPlans.docForm=async function(group,id){const d=id?(await API.request('/loading-plan-documents/'+id)).document:null,g=(await API.request('/loading-plans/'+(d?.group_id||group))).group;if(g.cancelled_at||['OUTBOUND','CANCELLED'].includes(d?.status))throw Error('此装车计划单已锁定或已取消');if(!g.invoice_no&&!d){Router.page('装车计划单（Loading Plan）',`<p>请先补充所属装车计划的发票及运输资料。</p><a class="button primary" href="/loading-plans/${g.id}/edit">编辑装车计划</a>`);return;}const values=d||g;Router.page(d?'编辑装车计划单（Loading Plan）':'新建装车计划单（Loading Plan）',this.context(g)+`<form id="lp-form" class="user-form"><input type="hidden" name="group_id" value="${g.id}">${d?'<p>装车计划单号：<strong data-no-i18n>'+esc(d.code)+'</strong></p>':'<p>装车计划单号将在保存时自动生成。</p>'}<div class="form-grid">${Object.entries(this.labels).map(([key,label])=>`<label>${label}<input name="${key}" type="${key==='planned_load_date'?'date':'text'}" maxlength="${key==='destination'?1000:key==='invoice_no'?78:key==='packing_list_no'||key==='vehicle_no'?80:160}" value="${esc(values[key]?.slice(0,key==='planned_load_date'?10:1000)||'')}" ${Object.hasOwn(this.headerLabels,key)?'readonly':''} ${key==='planned_load_date'?'required':''}></label>`).join('')}</div><p>发票和公共运输信息在所属装车计划中统一维护。</p><p><a href="/loading-plans/${g.id}/edit">编辑装车计划</a></p><p>生成正式装箱单前须补齐以上全部运输信息。修改已匹配计划单后，物流审核需要重新确认。</p><button class="button primary">保存装车计划单</button><p class="error" id="lp-error" role="alert"></p></form>`);this.bindSave($('lp-form'),'/loading-plan-documents'+(d?'/'+id:''),d,async r=>Router.go('/loading-plans/orders/'+r.id));};
const headerGroup=LoadingPlans.group.bind(LoadingPlans);LoadingPlans.group=async function(id){await headerGroup(id);const {group:g}=await API.request('/loading-plans/'+id),panel=document.createElement('section');panel.className='lp-load-summary';panel.innerHTML='<h3>公共运输资料</h3><dl class="lp-fields">'+Object.entries(this.headerLabels).map(([key,label])=>'<dt>'+label+'</dt><dd data-no-i18n>'+esc(g[key]||'待补充')+'</dd>').join('')+'</dl>';$('page-content').querySelector('.lp-context').after(panel);};
